/* Authenticated polling collaboration. The shared draft never enters local autosave. */
const StudioTeamWorkspace=(()=>{
 async function open(id){
  if(!studioBackend.enabled)return toast('Live teams require the account backend.');
  await studioBackend.flush();
  const url='/team/projects/'+encodeURIComponent(id);
  let state=await studioBackend.request(url);
  await window.Studio3DAssets.ready();
  const T=window.THREE,client=crypto.randomUUID(),request=(suffix='',method='GET',body)=>studioBackend.request(url+suffix,method,body);
  modal('Shared 3D workspace',`<p><b>${esc(state.project.name)}</b> · <span id="liveRole"></span> · <span id="liveVersion"></span></p><p>Other parts merge independently. Changes to the same part require review. Transforms, labels and visibility are shared; geometry and joint edits remain in the owner workspace.</p><p id="livePresence" role="status">Connecting…</p><div class="liveWorkspace"><div id="liveCanvas" aria-label="Shared assembly preview"></div><section><label>Part<select id="livePart"></select></label><div id="liveFields"></div><button type="button" id="liveReload">Reload selected part</button><button type="button" id="liveApply">Apply shared change</button><button type="button" id="liveDraft">Download my draft</button></section></div><p id="liveStatus" role="status"></p><p class="tiny">Presence expires after 20 seconds. Updates poll every 2 seconds while this tab is visible. This workspace requires the account server; the static preview cannot connect on its own.</p>`,()=>false);
  const dialog=document.getElementById('dialog');dialog.classList.add('liveDialog');document.querySelector('#modalForm>button[type=submit]').textContent='Close shared workspace';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();dialog.close();};
  const $=id=>document.getElementById(id),status=message=>{$('liveStatus').textContent=message;};
  let closed=false,busy=false,timer,raf,renderer,controls,selected=null,base=null,drawTicket=0,group=new T.Group(),dirty=false,accessLost=false;
  const scene=new T.Scene(),camera=new T.PerspectiveCamera(45,1,.01,100000);scene.background=new T.Color(0x15261e);scene.add(new T.HemisphereLight(0xffffff,0x536b58,2));const light=new T.DirectionalLight(0xffffff,3);light.position.set(20,40,20);scene.add(light,new T.GridHelper(100,50));scene.add(group);
  const dispose=g=>g.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});
  function selectPart(){base=structuredClone(state.project.assembly3d?.objects.find(o=>o.id===selected)||null);dirty=false;
   $('liveFields').innerHTML=base?`<label>Part name<input id="liveName" maxlength="80" value="${esc(base.name)}"></label>${['position','rotation'].map(key=>`<fieldset><legend>${key==='position'?'Position mm':'Rotation °'}</legend>${'XYZ'.split('').map((axis,i)=>`<label>${axis}<input type="number" step="any" id="live_${key}_${i}" value="${base[key][i]}"></label>`).join('')}</fieldset>`).join('')}<label><input type="checkbox" id="liveVisible" ${base.visible?'checked':''}> Visible</label>`:'<p>No shared parts. The owner must add geometry first.</p>';
   const linked=(state.project.assembly3d?.joints||[]).some(j=>j.parent===selected||j.child===selected),readonly=state.role==='viewer'||linked||!base;
   $('liveFields').querySelectorAll('input').forEach(i=>{i.disabled=readonly;i.oninput=()=>{dirty=true;};});$('liveApply').disabled=readonly;
   if(linked)status('This part is joint-linked. Edit it in the owner workspace.');
  }
  function draft(){if(!base)throw Error('Select a part first.');const next=structuredClone(base);next.name=$('liveName').value.trim();for(const key of ['position','rotation'])next[key]=[0,1,2].map(i=>Number($('live_'+key+'_'+i).value));next.visible=$('liveVisible').checked;const candidate=structuredClone(state.project.assembly3d);candidate.objects=candidate.objects.map(o=>o.id===next.id?next:o);if(!StudioAssembly.validate(candidate))throw Error('Enter valid part transforms and a non-empty name.');return next;}
  async function paint(frame=false){const ticket=++drawTicket,data=state.project.assembly3d||{version:1,units:'mm',objects:[]};
   for(const part of data.objects)if(part.model)await StudioSolidModel.prepare(part.model,part.dims.depth);
   if(closed||ticket!==drawTicket)return;
   const next=new T.Group();try{for(const part of data.objects){const mesh=window.Studio3DAssets.build(part);mesh.position.fromArray(part.position.map(v=>v/10));mesh.rotation.set(...part.rotation.map(v=>v*Math.PI/180));mesh.visible=part.visible;mesh.traverse(o=>{if(o.isMesh)o.material.wireframe=part.wireframe;});next.add(mesh);}}catch(e){dispose(next);throw e;}
   scene.remove(group);dispose(group);group=next;scene.add(group);
   if(frame&&controls){const box=new T.Box3().setFromObject(group);if(!box.isEmpty()){const centre=box.getCenter(new T.Vector3()),distance=Math.max(5,box.getSize(new T.Vector3()).length()*1.5);controls.target.copy(centre);camera.position.copy(centre).add(new T.Vector3(.7,.8,1).normalize().multiplyScalar(distance));controls.update();}}
   $('liveRole').textContent=state.role;$('liveVersion').textContent='version '+state.project.version;
   $('livePart').innerHTML=data.objects.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('');if(data.objects.some(o=>o.id===selected))$('livePart').value=selected;else{selected=data.objects[0]?.id||null;selectPart();}
  }
  try{renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));$('liveCanvas').appendChild(renderer.domElement);controls=new T.OrbitControls(camera,renderer.domElement);}catch(e){status('3D preview unavailable: '+e.message);}
  $('livePart').onchange=()=>{if(dirty){$('livePart').value=selected;return status('Apply or reload your draft before switching parts.');}selected=$('livePart').value;selectPart();};$('liveReload').onclick=()=>{selectPart();status('Selected part reloaded from the last server version.');};
  $('liveDraft').onclick=()=>{try{download('shared-part-draft.json',JSON.stringify({projectId:id,before:base,after:draft()},null,2),'application/json');}catch(e){status(e.message);}};
  $('liveApply').onclick=async()=>{if(busy)return;busy=true;$('liveApply').disabled=true;try{const next=draft();state=await request('/assembly','PATCH',{before:[base],after:[next]});if(closed)return;await paint();selectPart();status('Shared change saved. Unrelated part edits were preserved.');}catch(e){if(!closed)status(e.message+' Your fields are retained. Download your draft before reloading.');}finally{busy=false;if(!closed)$('liveApply').disabled=accessLost||state.role==='viewer'||!base||(state.project.assembly3d?.joints||[]).some(j=>j.parent===selected||j.child===selected);}};
  async function tick(){if(closed)return;if(!busy&&!document.hidden){busy=true;try{const pulse=await request('/presence','POST',{client_id:client,selected});if(closed)return;$('livePresence').textContent=pulse.peers.map(p=>p.name+(p.self?' (you)':'')+(p.selected?' · '+(state.project.assembly3d?.objects.find(o=>o.id===p.selected)?.name||'part'):'')).join(' | ')||'You are the first person here.';if(pulse.version!==state.project.version){state=await request();if(closed)return;await paint();if(dirty)status('The assembly changed. Your draft is retained; the server checks its part before saving.');else selectPart();}}catch(e){if(!closed){status('Connection paused: '+e.message+' Your draft is retained.');if([401,403,404].includes(e.status)){accessLost=true;$('liveApply').disabled=true;$('liveFields').querySelectorAll('input').forEach(i=>i.disabled=true);$('livePresence').textContent='Access unavailable. Your local draft is retained.';clearTimeout(timer);return;}}}finally{busy=false;}}if(!closed)timer=setTimeout(tick,2000);}
  function animate(){if(closed||!renderer)return;const host=$('liveCanvas');if(!host)return;const w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);if(renderer.domElement.width!==Math.round(w*renderer.getPixelRatio())||renderer.domElement.height!==Math.round(h*renderer.getPixelRatio()))renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();controls.update();renderer.render(scene,camera);raf=requestAnimationFrame(animate);}
  dialog.addEventListener('close',()=>{closed=true;clearTimeout(timer);cancelAnimationFrame(raf);controls?.dispose();renderer?.dispose();dispose(scene);dialog.classList.remove('liveDialog');request('/presence/'+client,'DELETE').catch(()=>{});toast('Shared workspace closed. Refresh your account workspace before making further owner edits.');},{once:true});
  await paint(true);selectPart();animate();tick();
 }
 return {open};
})();
